<script setup>
import { prepareProductPhoto } from '../utils/product-photo.js'
const props = defineProps({ user: { type: Object, required: true } })
const emptyFarm = () => ({ slug: '', name: '', contact: '', contactConsent: false, published: false, headline: '', tagline: '', coverImageUrl: '', theme: 'green', showHero: true })
const farm = reactive(emptyFarm())
const themes = [{ value: 'green', label: 'Green', color: '#285c34' }, { value: 'teal', label: 'Teal', color: '#16756d' }, { value: 'sage', label: 'Sage', color: '#687c56' }]
const previewColor = computed(() => themes.find(theme => theme.value === farm.theme)?.color || themes[0].color)
const isOwnedImage = url => /^\/api\/product-images\/[a-f0-9-]{36}$/.test(url || '')
const ownedCover = computed(() => isOwnedImage(farm.coverImageUrl))
const coverPicker = ref(null), coverCamera = ref(null)
const emptyProduct = () => ({ name: '', description: '', price: '', quantity: '', unit: 'kg', currency: 'NGN', imageUrl: '', published: false })
const draft = reactive(emptyProduct())
const products = ref([]), busy = ref(false), error = ref(''), feedback = ref(''), origin = ref('')
const loaded = ref(false), uploadingPhoto = ref(false)
const photoPicker = ref(null), cameraPicker = ref(null)
const ownedPhoto = computed(() => isOwnedImage(draft.imageUrl))
const activeTab = ref('products'), composerOpen = ref(false), search = ref(''), productFilter = ref('all')
const tabs = [{ value: 'products', label: 'Products' }, { value: 'design', label: 'Store design' }, { value: 'settings', label: 'Store settings' }]
const counts = computed(() => ({ total: products.value.length, published: products.value.filter(product => product.published).length, outOfStock: products.value.filter(product => Number(product.quantity) <= 0).length }))
const visibleProducts = computed(() => products.value.filter(product => (productFilter.value === 'all' || (productFilter.value === 'published' ? product.published : !product.published)) && `${product.name} ${product.description || ''}`.toLowerCase().includes(search.value.trim().toLowerCase())))
const previewProducts = computed(() => products.value.slice(0, 3))
const farmDirty = computed(() => JSON.stringify(farm) !== JSON.stringify({ ...emptyFarm(), ...savedFarm.value }))
let uploadController
let generation = 0
const savedFarm = ref({ slug: '', published: false })
const shareLink = computed(() => origin.value && savedFarm.value.slug ? `${origin.value}/${savedFarm.value.slug}/products` : '')
function openComposer() { if (busy.value || uploadingPhoto.value || !loaded.value) return; resetDraft(); composerOpen.value = true }
function closeComposer() { if (busy.value || uploadingPhoto.value) return; resetDraft(); composerOpen.value = false }
function selectTab(value) { if (!busy.value && !uploadingPhoto.value) activeTab.value = value }
function focusTab(event, index) {
  const offset = event.key === 'ArrowRight' ? 1 : event.key === 'ArrowLeft' ? -1 : 0
  const next = event.key === 'Home' ? 0 : event.key === 'End' ? tabs.length - 1 : offset ? (index + offset + tabs.length) % tabs.length : -1
  if (next < 0 || busy.value || uploadingPhoto.value) return
  event.preventDefault()
  selectTab(tabs[next].value)
  event.currentTarget.parentElement.querySelectorAll('[role="tab"]')[next]?.focus()
}
function saveFarm() { return save({ ...farm, action: 'configure' }, 'Storefront settings saved.') }
async function uploadPhoto(event, target = 'product') {
  const file = event.target.files?.[0]
  event.target.value = ''
  if (!file || busy.value || uploadingPhoto.value || !loaded.value) return
  error.value = ''; feedback.value = ''
  const token = generation
  uploadingPhoto.value = true
  const controller = new AbortController()
  uploadController = controller
  let preparing = true
  try {
    const photo = await prepareProductPhoto(file, { signal: controller.signal })
    if (token !== generation || controller.signal.aborted) return
    preparing = false
    const result = await $fetch('/api/product-images', { method: 'POST', body: photo, headers: { 'Content-Type': 'image/jpeg' }, timeout: 60000, signal: controller.signal })
    if (token !== generation || controller.signal.aborted) return
    if (target === 'cover') {
      farm.coverImageUrl = result.imageUrl
      feedback.value = 'Cover uploaded and GPS metadata removed. Save store design to attach it. It becomes public only when your farm is published and the welcome banner is enabled. No product attachment needed.'
    } else {
      draft.imageUrl = result.imageUrl
      feedback.value = 'Photo uploaded and GPS metadata removed. Save the product to attach it. It stays private until the product and storefront are published.'
    }
  } catch (cause) { if (token === generation) error.value = preparing ? (cause?.message || 'Could not prepare this photo. Try another picture.') : (cause?.data?.statusMessage || 'Photo upload was not confirmed. Try again when connected.') }
  finally { if (token === generation) uploadingPhoto.value = false }
}
function apply(data) { Object.assign(farm, emptyFarm(), data.farm); savedFarm.value = { ...data.farm }; products.value = data.products; loaded.value = true }
async function load() {
  const token = ++generation
  uploadController?.abort(); uploadingPhoto.value = false
  loaded.value = false
  activeTab.value = 'products'; composerOpen.value = false; search.value = ''; productFilter.value = 'all'
  products.value = []; savedFarm.value = { slug: '', published: false }; Object.assign(farm, emptyFarm()); resetDraft()
  busy.value = true; error.value = ''; feedback.value = ''
  try { const data = await $fetch('/api/marketplace', { timeout: 15000 }); if (token === generation) apply(data) }
  catch { if (token === generation) error.value = 'Could not load your catalog. Sign in and retry.' }
  finally { if (token === generation) busy.value = false }
}
async function save(input, message) {
  if (busy.value || uploadingPhoto.value || !loaded.value) return false
  const token = generation
  busy.value = true; error.value = ''; feedback.value = ''
  try {
    const data = await $fetch('/api/marketplace', { method: 'POST', body: input, timeout: 15000 })
    if (token !== generation) return false
    const localFarm = { ...farm }
    apply(data)
    if (input.action !== 'configure') Object.assign(farm, localFarm)
    feedback.value = message; return true
  } catch (cause) { if (token === generation) error.value = cause?.data?.statusMessage || 'Save was not confirmed. Refresh before retrying.'; return false }
  finally { if (token === generation) busy.value = false }
}
function resetDraft() { for (const key of Object.keys(draft)) delete draft[key]; Object.assign(draft, emptyProduct()) }
async function saveProduct() { if (await save({ ...draft, price: Number(draft.price), quantity: Number(draft.quantity), action: 'saveProduct' }, 'Product saved. Only published products appear on a published storefront.')) { resetDraft(); composerOpen.value = false } }
function edit(product) { if (busy.value || uploadingPhoto.value || !loaded.value) return; resetDraft(); Object.assign(draft, product); composerOpen.value = true; activeTab.value = 'products'; feedback.value = '' }
async function remove(product) { if (window.confirm(`Delete ${product.name}? This cannot be undone.`)) { if (await save({ action: 'deleteProduct', id: product.id }, 'Product deleted.') && draft.id === product.id) resetDraft() } }
async function copyLink() { try { await navigator.clipboard.writeText(shareLink.value); feedback.value = 'Storefront link copied.' } catch { feedback.value = 'Copy the storefront link from the field below.' } }
onMounted(() => { origin.value = window.location.origin; load() })
watch(() => props.user?.id, () => { if (origin.value) load() }, { flush: 'sync' })
onUnmounted(() => { generation++; uploadController?.abort() })
</script>

<template>
  <section class="marketplace" aria-label="Farm marketplace" :aria-busy="busy || uploadingPhoto">
    <header class="workspace-header">
      <div><p class="brand-note"><span aria-hidden="true">✿</span> FarmBuddy marketplace</p><h2>Your seller board</h2><p>Your harvest. Your storefront. Ready for buyers.</p></div>
      <div class="header-actions"><span class="store-status" :class="{ live: savedFarm.published }"><i aria-hidden="true"></i>{{ savedFarm.published ? 'Store published' : 'Store unpublished' }}</span><a v-if="shareLink && savedFarm.published" class="button secondary" :href="shareLink" target="_blank" rel="noopener">View store <span aria-hidden="true">↗</span></a><button v-else type="button" class="secondary" @click="selectTab('settings')" :disabled="busy || uploadingPhoto">Set up store</button></div>
    </header>
    <div class="workspace-tabs" role="tablist" aria-label="Seller workspace"><button v-for="(tab, index) in tabs" :id="`seller-tab-${tab.value}`" :key="tab.value" type="button" role="tab" :aria-selected="activeTab === tab.value" :tabindex="activeTab === tab.value ? 0 : -1" @keydown="focusTab($event, index)" :aria-controls="`seller-panel-${tab.value}`" :disabled="busy || uploadingPhoto" @click="selectTab(tab.value)">{{ tab.label }}<span v-if="tab.value === 'products'" class="tab-count">{{ products.length }}</span></button></div>
    <p v-if="error" class="notice error" role="alert">{{ error }}</p><p v-if="feedback" class="notice" role="status" aria-live="polite">{{ feedback }}</p>
    <p v-if="!loaded && busy" role="status" class="loading">Loading your farm…</p>
    <div v-if="!loaded && !busy" class="empty-state"><h3>Let's reconnect your catalog</h3><button type="button" @click="load">Retry loading</button></div>

    <section v-show="activeTab === 'products'" id="seller-panel-products" role="tabpanel" aria-labelledby="seller-tab-products">
      <template v-if="!composerOpen">
        <div class="section-heading"><div><h3>Fresh picks, all in one place</h3><p>Manage what buyers can discover on your farm.</p></div><button type="button" class="yellow" :disabled="busy || uploadingPhoto || !loaded" @click="openComposer"><span aria-hidden="true">＋</span> Add product</button></div>
        <div class="count-strip"><div><strong>{{ counts.total }}</strong><span>Total products</span></div><div><strong>{{ counts.published }}</strong><span>Published products</span></div><div><strong>{{ counts.outOfStock }}</strong><span>Out of stock</span></div></div>
        <div class="board-toolbar"><label class="search-field"><span class="sr-only">Search products</span><input v-model="search" type="search" placeholder="Search your harvest…"></label><div class="filters" aria-label="Filter products"><button v-for="filter in ['all', 'published', 'draft']" :key="filter" type="button" :aria-pressed="productFilter === filter" @click="productFilter = filter">{{ filter === 'all' ? 'All products' : filter === 'published' ? 'Published' : 'Drafts' }}</button></div></div>
        <ul v-if="visibleProducts.length" class="product-board"><li v-for="product in visibleProducts" :key="product.id" class="product-card">
          <div class="card-photo"><img v-if="isOwnedImage(product.imageUrl)" :src="product.imageUrl" :alt="product.name" loading="lazy"><div v-else class="photo-placeholder"><span aria-hidden="true">✿</span><small>{{ product.imageUrl ? 'External photo hidden' : 'Add a harvest photo' }}</small></div><span class="badge" :class="{ draft: !product.published }">{{ product.published ? 'Published' : 'Draft' }}</span></div>
          <div class="card-content"><div class="card-title"><h4>{{ product.name }}</h4><span class="stock-badge" :class="{ empty: Number(product.quantity) <= 0 }">{{ Number(product.quantity) <= 0 ? 'Out of stock' : 'In stock' }}</span></div><p class="price">{{ product.currency }} {{ Number(product.price).toFixed(2) }} <small>/ {{ product.unit }}</small></p><p class="stock-detail">{{ product.quantity }} {{ product.unit }} available</p><div class="card-actions"><button type="button" class="secondary edit-button" :disabled="busy || uploadingPhoto || !loaded" @click="edit(product)" :aria-label="`Edit ${product.name}`">Edit product</button><details class="card-menu"><summary :aria-label="`More actions for ${product.name}`">•••</summary><div><button type="button" :disabled="busy || uploadingPhoto || !loaded" @click="save({ ...product, action: 'saveProduct', published: !product.published }, 'Publication updated.')">{{ product.published ? 'Unpublish' : 'Publish' }}</button><button type="button" class="danger" :disabled="busy || uploadingPhoto || !loaded" @click="remove(product)">Delete</button></div></details></div></div>
        </li></ul>
        <div v-else-if="loaded" class="empty-state"><span class="empty-flower" aria-hidden="true">✿</span><h3>{{ products.length ? 'No matching products' : 'Your next harvest starts here' }}</h3><p>{{ products.length ? 'Try a different search or filter.' : 'Add a photo, set your price, and make your first product ready for buyers.' }}</p><button v-if="!products.length" type="button" class="yellow" @click="openComposer">Add your first product</button><button v-else type="button" class="secondary" @click="search = ''; productFilter = 'all'">Clear filters</button></div>
      </template>
      <form v-else class="composer" @submit.prevent="saveProduct">
        <div class="section-heading"><div><p class="muted">Product workspace</p><h3>{{ draft.id ? 'Edit your product' : 'A new addition to your farm' }}</h3></div><button type="button" class="secondary" :disabled="busy || uploadingPhoto" @click="closeComposer">Cancel &amp; close</button></div>
        <fieldset :disabled="busy || uploadingPhoto || !loaded" class="composer-layout"><legend class="sr-only">Product details</legend>
          <section class="composer-photo"><h4><span class="step">1</span> Give it a good photo</h4><div class="upload-canvas"><img v-if="ownedPhoto" :src="draft.imageUrl" alt="Your uploaded product photo"><div v-else class="photo-placeholder"><span aria-hidden="true">✿</span><p>A fresh look at what you grow</p></div></div>
            <input id="product-photo-upload" aria-label="Choose product photo" ref="photoPicker" type="file" accept="image/jpeg,image/png,image/webp" class="sr-only" @change="uploadPhoto"><input id="product-photo-camera" aria-label="Take product photo" ref="cameraPicker" type="file" accept="image/jpeg,image/png,image/webp" capture="environment" class="sr-only" @change="uploadPhoto">
            <div class="photo-actions"><button type="button" @click="photoPicker?.click()">Choose photo</button><button type="button" class="secondary" @click="cameraPicker?.click()">Take a photo</button><button v-if="draft.imageUrl" type="button" class="text-button" @click="draft.imageUrl = ''">Remove from product</button></div>
            <details class="helper"><summary>Photo requirements &amp; privacy</summary><p>JPEG, PNG or WebP, up to 20 MB and 40 megapixels. Your browser reduces it to 1600 pixels. The server checks photos and removes location metadata. Save to attach the upload. It stays private until the product and storefront are published. Removing only detaches it, not deletes the stored upload.</p></details>
            <details class="helper"><summary>Use an external image URL</summary><label>Image URL (public HTTPS only)<input v-model="draft.imageUrl" type="text" maxlength="1000" placeholder="https://images.example.com/tomatoes.jpg"></label><p>External photos are not loaded here. They may reveal a visitor's IP to the image host. Use a trusted host, never a private or signed URL.</p></details>
          </section>
          <div class="composer-details"><section class="editor-section"><h4><span class="step">2</span> The essentials</h4><label>Product name<input v-model="draft.name" required maxlength="120" placeholder="Fresh garden tomatoes"></label><label>Description<textarea v-model="draft.description" maxlength="2000" rows="3" placeholder="What makes this harvest special?" /></label></section>
          <section class="editor-section"><h4><span class="step">3</span> Price &amp; stock</h4><div class="fields"><label>Price per unit<input v-model="draft.price" type="number" required min="0.01" max="1000000000" step="0.01" placeholder="0.00"></label><label>Currency<select v-model="draft.currency"><option v-for="code in ['NGN','USD','GBP','EUR','GHS','KES','ZAR']" :key="code">{{ code }}</option></select></label><label>Quantity available<input v-model="draft.quantity" type="number" required min="0" max="1000000000" step="any" placeholder="0"></label><label>Unit<input v-model="draft.unit" required maxlength="40" placeholder="kg, crate, bag"></label></div></section>
          <section class="publish-box"><h4><span class="step">4</span> Ready for buyers?</h4><label class="check"><input v-model="draft.published" type="checkbox"> Publish this product on my published storefront</label><p>Leave unchecked to save a private draft. Saving a product never publishes your store.</p></section></div>
        </fieldset>
        <p v-if="uploadingPhoto" role="status" class="notice">Preparing and uploading your photo. Keep this page open.</p>
        <footer class="save-bar"><span>Changes are saved only when you choose Save.</span><button :disabled="busy || uploadingPhoto || !loaded">{{ busy ? 'Saving…' : draft.id ? 'Save changes' : 'Save product' }}</button></footer>
      </form>
    </section>

    <section v-show="activeTab === 'design'" id="seller-panel-design" role="tabpanel" aria-labelledby="seller-tab-design">
      <div class="section-heading"><div><h3>A storefront that feels like you</h3><p>Style your welcome. Let your harvest do the talking.</p></div><span class="draft-note">{{ farmDirty ? 'Unsaved changes' : 'Settings saved' }}</span></div>
      <div class="design-layout"><form class="design-controls" @submit.prevent="saveFarm"><fieldset :disabled="busy || uploadingPhoto || !loaded"><legend class="sr-only">Store appearance</legend>
        <section class="editor-section"><h4>Welcome banner</h4><label class="check"><input v-model="farm.showHero" type="checkbox"> Show the welcome banner</label><label>Headline<input v-model="farm.headline" maxlength="80" placeholder="Fresh from our farm"></label><label>Tagline<input v-model="farm.tagline" maxlength="160" placeholder="A little about what you grow"></label></section>
        <section class="editor-section"><h4>Your farm's colors</h4><fieldset class="theme-options"><legend class="sr-only">Store colors</legend><label v-for="theme in themes" :key="theme.value" class="theme-choice"><input v-model="farm.theme" type="radio" name="store-theme" :value="theme.value"><span class="swatch" :style="{ backgroundColor: theme.color }" aria-hidden="true"></span>{{ theme.label }}</label></fieldset></section>
        <section class="editor-section"><h4>Cover photo</h4><img v-if="ownedCover" class="cover-thumbnail" :src="farm.coverImageUrl" alt="Your uploaded cover photo"><input ref="coverPicker" type="file" accept="image/jpeg,image/png,image/webp" class="sr-only" aria-label="Choose cover photo" @change="uploadPhoto($event, 'cover')"><input ref="coverCamera" type="file" accept="image/jpeg,image/png,image/webp" capture="environment" class="sr-only" aria-label="Take cover photo" @change="uploadPhoto($event, 'cover')"><div class="photo-actions"><button type="button" class="secondary" @click="coverPicker?.click()">Choose cover</button><button type="button" class="secondary" @click="coverCamera?.click()">Take photo</button><button v-if="farm.coverImageUrl" type="button" class="text-button" @click="farm.coverImageUrl = ''">Clear cover</button></div><details class="helper"><summary>Photo privacy &amp; requirements</summary><p>JPEG, PNG or WebP, up to 20 MB and 40 megapixels. Reduced to 1600 pixels before upload, checked by the server, and location metadata removed. Covers become public only when your farm is published and the welcome banner is enabled. No product attachment needed. A photo attached to a published product on a published storefront can also be public. Save to attach or clear. Clearing only detaches, not deletes the stored upload.</p></details></section>
        <button class="wide" :disabled="busy || uploadingPhoto || !loaded">{{ busy ? 'Saving…' : 'Save store design' }}</button><p class="save-hint">Saves all store settings, including edits in Store settings. Does not automatically publish your store.</p>
      </fieldset></form>
      <aside class="preview-wrap"><div class="preview-toolbar"><span class="preview-dot" aria-hidden="true"></span><strong>Preview</strong><small>Not a live store</small></div><div class="store-preview" :style="{ '--preview-color': previewColor }" aria-label="Store appearance preview"><div class="mock-nav"><span aria-hidden="true">✿</span><strong>{{ farm.name || 'Your farm' }}</strong><span>Farm shop</span></div><div v-if="farm.showHero" class="mock-hero"><img v-if="ownedCover" :src="farm.coverImageUrl" alt="Your uploaded cover photo"><div><h4>{{ farm.headline || farm.name || 'Your farm' }}</h4><p v-if="farm.tagline">{{ farm.tagline }}</p></div></div><div class="mock-products"><h5>From our farm</h5><p class="mock-caption">Sample layout · products shown for preview</p><div class="mock-grid"><article v-for="product in previewProducts" :key="product.id"><img v-if="isOwnedImage(product.imageUrl)" :src="product.imageUrl" :alt="product.name"><div v-else class="mock-photo" aria-hidden="true">✿</div><strong>{{ product.name }}</strong><small>{{ product.currency }} {{ Number(product.price).toFixed(2) }} / {{ product.unit }}</small></article><template v-if="!previewProducts.length"><article v-for="item in ['Your fresh harvest', 'Your next pick', 'Grown with care']" :key="item"><div class="mock-photo" aria-hidden="true">✿</div><strong>{{ item }}</strong><small>Sample product</small></article></template></div></div></div><p class="save-hint">Preview only. Changes go live after you save settings on a published storefront.</p></aside></div>
      <p v-if="uploadingPhoto" role="status" class="notice">Preparing and uploading cover photo. Keep this page open.</p>
    </section>

    <section v-show="activeTab === 'settings'" id="seller-panel-settings" role="tabpanel" aria-labelledby="seller-tab-settings">
      <div class="section-heading"><div><h3>The roots of your store</h3><p>Your farm details, public contact, and publication controls.</p></div><span class="draft-note">{{ farmDirty ? 'Unsaved changes' : 'Settings saved' }}</span></div>
      <div class="settings-layout"><form class="settings-form" @submit.prevent="saveFarm"><fieldset :disabled="busy || uploadingPhoto || !loaded"><legend class="sr-only">Storefront settings</legend><section class="editor-section"><h4>Farm identity</h4><label>Public farm name<input v-model="farm.name" required maxlength="100" autocomplete="organization" placeholder="Your farm name"></label><label>Unique farm slug<input v-model="farm.slug" required minlength="3" maxlength="60" pattern="[a-z0-9]+(-[a-z0-9]+)*" placeholder="green-acre-farm" autocapitalize="none" spellcheck="false"></label><p class="save-hint">Lowercase letters, digits and hyphens. Changing the slug changes your link on this website, not a custom domain.</p></section><section class="editor-section"><h4>How buyers reach you</h4><label>Public ordering contact (optional)<input v-model="farm.contact" maxlength="250" placeholder="Business phone or ordering email"></label><label class="check"><input v-model="farm.contactConsent" type="checkbox"> I consent to displaying this contact publicly.</label><p class="save-hint">Your account email is never filled in automatically. To remove consent, clear the contact field too.</p></section><section class="publish-box"><h4>Store visibility</h4><label class="check"><input v-model="farm.published" type="checkbox"> Publish this storefront, its farm name and explicitly published products</label><p>Buyers contact you directly. No online checkout, payment processing or automatic stock reservation.</p></section><button :disabled="busy || uploadingPhoto || !loaded">{{ busy ? 'Saving…' : 'Save storefront settings' }}</button><p class="save-hint">Saves all store settings, including your store design. Nothing publishes until you save.</p></fieldset></form>
      <aside class="link-card"><span class="link-symbol" aria-hidden="true">↗</span><h4>Your farm, one link</h4><p>Share your saved storefront with buyers.</p><template v-if="shareLink"><label>Storefront link<input :value="shareLink" readonly aria-label="Storefront share link"></label><button type="button" class="yellow wide" @click="copyLink">Copy link</button><a v-if="savedFarm.published" :href="shareLink" target="_blank" rel="noopener">Open storefront</a><p v-else class="save-hint">Storefront is unpublished. Visitors will see an unavailable page.</p></template><p v-else class="save-hint">Save your farm name and slug to create a link.</p><p class="save-hint">This link reflects saved settings, not unsaved edits.</p></aside></div>
    </section>
    <footer class="workspace-footer"><span>Made for what you grow.</span><button type="button" class="text-button" :disabled="busy || uploadingPhoto" @click="load">Refresh catalog</button></footer>
  </section>
</template>

